<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { addCart, listAppCategories, listAppDishes } from '../../api/app'
import type { Category, Dish } from '../../api/types'
const route = useRoute(); const router = useRouter(); const stallId = Number(route.params.stallId); const categories = ref<Category[]>([]); const dishes = ref<Dish[]>([]); const categoryId = ref<number>(); const loading = ref(false)
const currentCategory = computed(() => categories.value.find(c => c.id === categoryId.value)?.name || '菜单')
async function loadDishes(id: number) { categoryId.value = id; loading.value = true; try { dishes.value = await listAppDishes(id) } finally { loading.value = false } }
async function add(dish: Dish) { await addCart(dish.id); ElMessage.success(`已加入购物车：${dish.name}`) }
onMounted(async () => { categories.value = await listAppCategories(stallId); if (categories.value[0]) await loadDishes(categories.value[0].id) })
</script>
<template><div class="mobile-page menu-page"><el-page-header title="返回" @back="router.back()"><template #content><strong>档口菜单</strong></template></el-page-header><div class="menu-layout"><aside class="category-list"><button v-for="category in categories" :key="category.id" :class="{ active: category.id === categoryId }" @click="loadDishes(category.id)">{{ category.name }}</button></aside><section v-loading="loading" class="dish-list"><h2>{{ currentCategory }}</h2><article v-for="dish in dishes" :key="dish.id" class="dish-card"><div class="dish-cover">{{ dish.name.slice(0, 1) }}</div><div class="dish-info"><strong>{{ dish.name }}</strong><p>{{ dish.description || '现点现做' }}</p><b>¥{{ dish.price }}</b></div><el-button type="primary" circle size="small" @click="add(dish)">+</el-button></article><div v-if="!dishes.length" class="empty">这个分类还没有上架菜品</div></section></div><div class="cart-bar"><span>选餐后请在购物车确认取餐时段</span><el-button type="primary" @click="router.push('/student/cart')">查看购物车</el-button></div></div></template>
<style scoped>.menu-layout{display:grid;grid-template-columns:76px 1fr;gap:10px;margin-top:12px;align-items:start}.category-list{position:sticky;top:8px;display:grid;align-content:start;border:1px solid #dde5e1;background:#fff}.category-list button{border:0;border-bottom:1px solid #edf0ee;background:#fff;color:#73817d;padding:13px 7px;text-align:center;cursor:pointer;font-size:12px}.category-list button:last-child{border-bottom:0}.category-list button.active{background:#edf5f1;color:#146b5c;font-weight:700;box-shadow:inset 3px 0 0 #146b5c}.dish-list h2{font-size:16px;margin:0 0 7px;padding:8px 4px 5px;color:#334641}.dish-card{display:flex;gap:10px;align-items:center;background:#fff;border:1px solid #dde5e1;border-radius:4px;padding:11px;margin-bottom:7px}.dish-cover{width:44px;height:44px;border-radius:3px;background:#f2eadf;color:#9a6036;display:grid;place-items:center;font-weight:700;font-size:15px}.dish-info{flex:1;min-width:0}.dish-info strong{font-size:13px}.dish-info p{font-size:11px;color:#87938f;margin:4px 0;line-height:1.5}.dish-info b{color:#a35d31;font-size:14px}.dish-card :deep(.el-button){width:27px;height:27px;min-height:27px}.cart-bar{position:sticky;bottom:62px;display:flex;align-items:center;justify-content:space-between;background:#fff;color:#334641;border:1px solid #cfdad5;border-left:4px solid #146b5c;border-radius:3px;padding:10px 11px;margin-top:12px;font-size:11px;box-shadow:0 -4px 14px rgba(31,57,49,.06)}.cart-bar .el-button{margin-left:8px;height:34px}</style>
